{"command": "python3 << 'EOF'
from rdkit import Chem

smiles = "Cc1c(C(=O)Nc2ccc(-c3nc(Br)cnc3N)cc2)c(=O)n(-c2ccccc2)n1C"
mol = Chem.MolFromSmiles(smiles)

if mol:
    print(f"Molecule is valid")
    print(f"Formula: {Chem.rdMolDescriptors.CalcMolFormula(mol)}")
    print(f"MW: {Chem.Descriptors.MolWt(mol)}")

    # Find amide bonds
    for bond in mol.GetBonds():
        if bond.GetBondType() == Chem.BondType.SINGLE:
            a1 = bond.GetBeginAtom()
            a2 = bond.GetEndAtom()
            if (a1.GetSymbol() == 'C' and a2.GetSymbol() == 'N') or (a1.GetSymbol() == 'N' and a2.GetSymbol() == 'C'):
                # Check if C is carbonyl
                for nb in a1.GetNeighbors():
                    if nb.GetSymbol() == 'O' and a1.GetBondWithIdx(a1.GetIdx(nb)).GetBondType() == Chem.BondType.DOUBLE:
                        print(f"Amide bond: C({a1.GetIdx()})-N({a2.GetIdx()})")
                        break

    # Find the aryl-pyridine connection
    print("\nLooking for aryl-pyridine connection...")
    for bond in mol.GetBonds():
        if bond.GetBondType() == Chem.BondType.SINGLE:
            a1 = bond.GetBeginAtom()
            a2 = bond.GetEndAtom()
            if a1.IsInRing() and a2.IsInRing() and a1.GetIsAromatic() and a2.GetIsAromatic():
                ring1 = a1.GetRingInfo().AtomRings()
                ring2 = a2.GetRingInfo().AtomRings()
                # Check if one is pyridine-like (has N)
                has_n_1 = any(n.GetSymbol() == 'N' for n in a1.GetNeighbors())
                has_n_2 = any(n.GetSymbol() == 'N' for n in a2.GetNeighbors())
                print(f"Aryl-Aryl bond: {a1.GetIdx()}-{a2.GetIdx()}, N in neighbors: {has_n_1}/{has_n_2}")

else:
    print("Invalid SMILES")
EOF
